#include <stdio.h>
int in_range(int value) {
  return value >= 4 && value <= 7;
}
int main(void) {
  int count = 0;
  for (int i = 0; i < 5; i++) {
    int value;
    scanf("%d", &value);
    count += in_range(value);
  }
  printf("count=%d\n", count);
  return 0;
}

